def comps(g,bg):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                q=[(i,j)];c=g[i][j];seen.add((i,j));cells=[]
