def flood(g,start,bg):
    h,w=len(g),len(g[0]); seen=set(); q=[start];res=[]
    while q:
        x,y=q.pop()
        if g[x][y]==bg and (x,y) not in seen: seen.add((x,y));res.append((x,y))
