def classify(g,bg):
    h,w=len(g),len(g[0])
    reach=[[False]*w for _ in range(h)]; q=deque()
    for i in [0,h-1]:
        for j in range(w):
            if g[i][j]==bg: reach[i][j]=True;q.append((i,j))
    for j in [0,w-1]:
        for i in range(h):
            if g[i][j]==bg: reach[i][j]=True;q.append((i,j))
    while q:
        x,y=q.popleft()
        for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
            p=(x+dx,y+dy)
            if 0<=p[0]<h and 0<=p[1]<w and g[p[0]][p[1]]==bg and not reach[p[0]][p[1]]:
                reach[p[0]][p[1]]=True;q.append(p)
    inner={(i,j) for i in range(h) for j in range(w) if g[i][j]==bg and not reach[i][j]}
    seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j];qq=[(i,j)];seen.add((i,j));cells=[]
                while qq:
                    a,b=qq.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        p=(a+da,b+db)
                        if 0<=p[0]<h and 0<=p[1]<w and g[p[0]][p[1]]==col and p not in seen:
                            seen.add(p);qq.append(p)
                inter=len(set(cells)&inner)
                # does shape touch any bg cell inside its bbox? bounding box expansion
                rs=[c for _,c in cells];cs=[c for c,_ in cells]
                R1,R2,C1,C2=min(rs),max(rs),min(cs),max(cs)
                adj=any(0<=r<h and 0<=c<w and g[r][c]==bg for r in range(R1,R2+1) for c in range(C1,C2+1))
                out.append((col,len(cells),inter,adj,(R2-R1+1)*(C2-C1+1)))
    return out
